package kr.workbench;
import burp.api.montoya.*;import burp.api.montoya.http.*;import burp.api.montoya.http.message.*;import burp.api.montoya.http.message.requests.*;import burp.api.montoya.internal.*;import burp.api.montoya.core.*;import javax.swing.*;import javax.swing.table.*;import java.util.*;import java.util.List;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** API adapter regression. Native execution is separately recorded. */
public final class AuthRecordTest extends WorkbenchTest {
 static void idle(AuthComparePanel p)throws Exception{for(int i=0;i<800;i++){edt(()->{});if(p.active.get()==0)return;Thread.sleep(10);}throw new AssertionError("auth worker timeout");}
 static HttpRequest q(String cookie){return request("https://auth.test/object/101","GET",true,List.of(header("Cookie",cookie),header("Authorization","Bearer "+cookie),header("X-CSRF-Token","csrf-"+cookie),header("Accept","application/json")));}
 static HttpRequestResponse rr(HttpRequest q,burp.api.montoya.http.message.responses.HttpResponse s){return proxy(HttpRequestResponse.class,(p,m,a)->switch(m.getName()){case "request"->q;case "response"->s;default->def(m);});}
 public static void main(String[] args)throws Exception{
  ObjectFactoryLocator.FACTORY=proxy(MontoyaObjectFactory.class,(p,m,a)->{if(m.getName().equals("requestOptions"))return proxy(RequestOptions.class,(pp,mm,aa)->pp);if(m.getName().equals("httpRequestResponse"))return rr((HttpRequest)a[0],(burp.api.montoya.http.message.responses.HttpResponse)a[1]);return def(m);});
  AtomicInteger sent=new AtomicInteger();List<HttpRequest> emitted=new CopyOnWriteArrayList<>();var http=proxy(Http.class,(p,m,a)->{if(!m.getName().equals("sendRequest"))return def(m);HttpRequest req=(HttpRequest)a[0];sent.incrementAndGet();emitted.add(req);boolean blocked=req.headers().stream().anyMatch(h->h.name().equalsIgnoreCase("cookie")&&h.value().equals("B"));return rr(req,response(blocked?403:200,blocked?"{\n\"error\":\"denied\"\n}":"{\n\"owner\":\"A\"\n}"));});
  MontoyaApi api=proxy(MontoyaApi.class,(p,m,a)->m.getName().equals("http")?http:def(m));HttpRequest original=q("ADMIN");var baseline=response(200,"{\n\"owner\":\"A\"\n}");AtomicReference<List<HttpRequestResponse>> selected=new AtomicReference<>(List.of(rr(original,baseline)));AtomicReference<AuthComparePanel> box=new AtomicReference<>();edt(()->box.set(new AuthComparePanel(api,selected::get)));AuthComparePanel p=box.get();
  edt(()->{check(p.history.getColumnCount()==9&&p.history.getColumnName(0).equals("NO")&&p.history.getColumnName(1).equals("메서드")&&p.history.getColumnName(2).equals("URL")&&p.history.getColumnName(3).equals("종합 결과")&&p.history.getColumnName(4).equals("계정 1"),"per-account history columns");check(p.packets.getTabCount()==5&&p.packets.getTitleAt(0).equals("비교 계정 1"),"four target packet tabs plus original");
   p.observe(q("A"),baseline);p.observe(q("B"),baseline);p.observe(q("A"),baseline);check(p.credentials.size()==2,"combined cookies and bearer deduplicated");check(p.credentials.values().iterator().next().count()==2,"repeat count preserved");
   HttpRequest rotated=request("https://auth.test/object/101","GET",true,List.of(header("Cookie","A"),header("Authorization","Bearer A"),header("X-CSRF-Token","rotated")));p.observe(rotated,baseline);check(p.credentials.size()==2,"CSRF rotation is auxiliary not a new identity");check(p.credentials.values().iterator().next().headers().get("x-csrf-token").equals("rotated"),"latest auxiliary token retained");
   check(p.candidateModel.getColumnCount()==6&&p.candidateModel.getValueAt(0,4).toString().contains("Bearer A"),"candidate metadata columns and visible credential values");p.candidates.setRowSelectionInterval(0,0);JPopupMenu popup=(JPopupMenu)p.candidates.getClientProperty("wb.auth.popup");((JMenuItem)popup.getComponent(0)).doClick();check(p.slots[0]!=null,"right-click action assigns exact selected candidate");p.assign(1,new ArrayList<>(p.credentials.values()).get(1));p.anonymous(2);check(p.slots[2].headers().isEmpty(),"explicit anonymous profile");
   p.observe(request("https://other.test/","GET",true,List.of(header("Cookie","A"))),baseline);check(p.credentials.size()==3,"same secret isolated by Origin");try{p.assign(2,new ArrayList<>(p.credentials.values()).get(2));throw new AssertionError();}catch(IllegalArgumentException e){check(true,"cross-origin profile assignment rejected");}
   p.begin(original,ToolType.PROXY,10);check(p.tickets.isEmpty(),"Record OFF emits no automatic job");
  });check(sent.get()==0,"passive collection and assignment emit zero requests");
  edt(p::compareSelection);idle(p);check(sent.get()==4,"manual comparison verifies baseline then sends one request per profile");check(emitted.get(1).headers().stream().anyMatch(h->h.name().equalsIgnoreCase("cookie")&&h.value().equals("A")),"profile A cookie applied");check(emitted.get(1).headers().stream().anyMatch(h->h.name().equalsIgnoreCase("x-csrf-token")&&h.value().equals("rotated")),"profile CSRF applied instead of original");check(emitted.get(3).headers().stream().noneMatch(h->p.authNames.contains(h.name().toLowerCase(Locale.ROOT))||AuthComparePanel.CSRF.contains(h.name().toLowerCase(Locale.ROOT))),"anonymous request removes all captured credentials and CSRF");
  edt(()->{check(p.runs.size()==1&&p.runs.get(0).packets[1].response.statusCode()==403,"one grouped history row contains all profile responses");check(p.responses[0].getHighlighter().getHighlights().length>0&&p.requests[0].getHighlighter().getHighlights().length>0,"response and credential differences highlighted");p.colors.setSelected(false);p.show(p.current());check(p.responses[0].getHighlighter().getHighlights().length==0,"difference colors can be disabled");p.colors.setSelected(true);p.mode.setSelectedIndex(1);check(p.responses[0].getText().contains("owner"),"original comparison keeps packet text");
   p.startRecord();try{p.clearSlot(0);throw new AssertionError();}catch(IllegalArgumentException e){check(true,"Record freezes assigned profiles");}p.begin(original,ToolType.EXTENSIONS,20);check(p.tickets.isEmpty(),"extension replays cannot recursively enter Record");p.begin(original,ToolType.PROXY,21);check(p.tickets.containsKey(21),"request-time Record ticket");p.received(21,original,baseline);
  });edt(()->{});idle(p);check(sent.get()==8&&p.runs.size()==2,"Record ticket creates an independent history row for same URL");
  edt(()->{p.begin(original,ToolType.PROXY,22);p.stop();p.received(22,original,baseline);});edt(()->{});check(sent.get()==8,"Stop drops outstanding Record tickets");
  selected.set(List.of(rr(request("https://auth.test/write","POST",true,List.of()),baseline)));edt(()->{try{p.compareSelection();throw new AssertionError();}catch(IllegalArgumentException e){check(true,"write replay requires explicit option");}});
  selected.set(List.of(rr(request("https://auth.test/out","GET",false,List.of()),baseline)));edt(()->{try{p.compareSelection();throw new AssertionError();}catch(IllegalArgumentException e){check(true,"out-of-scope replay rejected");}});
  selected.set(List.of(rr(original,baseline)));edt(p::compareSelection);for(int i=0;i<100&&sent.get()<10;i++)Thread.sleep(5);edt(p::stop);idle(p);check(sent.get()==10,"Stop prevents remaining profile sends");
  edt(()->{((TableRowSorter<?>)p.history.getRowSorter()).setSortKeys(List.of(new RowSorter.SortKey(0,SortOrder.DESCENDING)));p.history.setRowSelectionInterval(0,0);check(p.current().no==3,"sorted history resolves correct grouped packets");p.clearHistory();check(p.history.getRowCount()==0&&p.current()==null,"clear removes stale details");});
  String a="GET / HTTP/1.1\r\nCookie: A\r\nX-N: 1\r\n\r\nalpha",b="GET / HTTP/1.1\r\nCookie: B\r\nX-N: 2\r\n\r\nbeta";var diff=PacketDiff.compare(new String[]{a,b,null},Set.of("cookie"));check(diff[0].ranges().stream().anyMatch(r->r.kind()==PacketDiff.Kind.AUTH)&&diff[0].ranges().stream().anyMatch(r->r.kind()==PacketDiff.Kind.HEADER)&&diff[0].ranges().stream().anyMatch(r->r.kind()==PacketDiff.Kind.BODY),"authentication/header/body distinct highlight classes");check(diff[0].text().equals(a.replace("\r\n","\n")),"diff never inserts synthetic alignment lines");check(PacketDiff.compare(new String[]{a,a},Set.of())[0].ranges().isEmpty(),"identical packets have no differences");check(PacketDiff.compare(new String[]{"x".repeat(80000),"b"},Set.of())[0].limited(),"packet preview bounded at 64K characters");
  edt(()->{for(int i=0;i<120;i++)p.observe(q("new-"+i),baseline);check(p.credentials.size()==100,"candidate retention bounded at 100");p.close();});edt(()->{});check(p.credentials.isEmpty()&&p.runs.isEmpty()&&p.worker.isShutdown(),"unload clears credentials/history and stops worker");System.out.println("AuthRecordTest: "+checks+" checks passed");
 }
}
